namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly List<Notification> _notifications;
    private int _nextId;

    public NotificationService()
    {
        _notifications = new List<Notification>
        {
            new(1, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-30)),
            new(2, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-20)),
            new(3, "New feature available: dark mode.", DateTime.UtcNow.AddMinutes(-10)),
        };
        _nextId = 4;
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(int lastId)
    {
        lock (_notifications)
        {
            var newer = _notifications.Where(n => n.Id > lastId).ToList();
            return Task.FromResult(newer);
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Called internally by the polling page; in a real app this would come from a DB or message queue.
    /// </summary>
    public Task<Notification?> GenerateRandomNotificationAsync()
    {
        // ~30% chance a new notification appears each poll
        if (Random.Shared.Next(100) < 30)
        {
            var messages = new[]
            {
                "Someone liked your post.",
                "You have a new follower.",
                "Server maintenance scheduled.",
                "Your export is ready to download.",
                "A comment was added to your thread.",
            };

            var notification = new Notification(
                _nextId,
                messages[Random.Shared.Next(messages.Length)],
                DateTime.UtcNow);

            lock (_notifications)
            {
                _notifications.Add(notification);
                _nextId++;
            }

            return Task.FromResult<Notification?>(notification);
        }

        return Task.FromResult<Notification?>(null);
    }
}

